$ErrorActionPreference = 'Stop'
$root = 'src\editors\website'
if (!(Test-Path (Join-Path $root 'WebsiteEditor.tsx'))) { throw 'Run this script from the Onyx Studio project root.' }
$changes = @(
  @{ Name = 'WebsiteEditor.tsx'; Sha = 'F8FA6BF4A721D7405F2005686E6A0B8535E111AB8DA2BD02A6F621D5B54089D6'; Data = '' }
  @{ Name = 'websiteTypes.ts'; Sha = 'CC428122E0BBFA52400C3319F3815F72BD0FBFD3BF490201EEC293D6D9E97914'; Data = '' }
  @{ Name = 'websiteExporter.ts'; Sha = '2577794993CD71909FDC0664D8CE723699F483A59FA6DCB196EEDF92BE20F8B2'; Data = '' }
)
if (!(Test-Path (Join-Path $root 'WebsiteStyleInspector.tsx'))) { throw 'Install the Typography and Appearance upgrade first. No changes made.' }
foreach ($item in $changes) {
  $path = Join-Path $root $item.Name
  if (!(Test-Path $path)) { throw "Missing $path. No changes made." }
  $hash = (Get-FileHash -Algorithm SHA256 $path).Hash
  if ($hash -ne $item.Sha) { throw "$($item.Name) differs from the expected version. No changes made. Upload the current file for a tailored patch." }
}
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backups = @()
try {
  foreach ($item in $changes) {
    $path = Join-Path $root $item.Name
    $backup = "$path.$stamp.bak"
    Copy-Item $path $backup
    $backups += @{ Path = $path; Backup = $backup }
    $absolute = (Resolve-Path $path).Path
    [System.IO.File]::WriteAllBytes($absolute, [Convert]::FromBase64String($item.Data))
    Write-Host "Updated $path"
  }
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
  Write-Host 'Divider, keyboard shortcuts, borders, and toolbar labels installed.' -ForegroundColor Green
} catch {
  foreach ($item in $backups) { Copy-Item $item.Backup $item.Path -Force }
  Write-Host 'Original files restored. See the error above.' -ForegroundColor Yellow
  throw
}
